window.LD=window.LD||{};window.LD["party/p3"]={"id":"p3","name":"The Azure Gravediggers","poss":"The Azure Gravediggers'","members":["h3","h15","h5","h9"],"leader":"h3","morale":100,"disposition":"honorable","motto":"We return lost purses. Annoyingly.","banner":{"c1":"#3c64c8","c2":"#e8e8e8","emblem":"skull"},"loc":"emberdeep","loc_name":"Emberdeep","goal":{"text":"to finish the season as one of the top three parties","kind":"top","done":null,"progress":"finished 5th","missed":true,"crew":"The Azure Gravediggers","party":"p3"},"vows":[{"text":"never to retreat","day":1,"state":"broken","ended":83,"through":false,"progress":"broken on day 23 of season 3","crew":"The Azure Gravediggers","party":"p3"}],"doing":"last seen delving into Emberdeep","progress":null,"today":["XP: Duren +4.","Coin between them: -3 silver.","Ate 4 rations."],"fights_today":[],"why":null,"founded_day":1,"founded_season":1,"disbanded":null,"anthem":{"src":"book","id":"salt_on_the_wind","title":"Salt on the Wind","tone":"sad","meter":"6/8","bpm":69,"diff":3,"day":27,"night":null,"n":8,"by":null,"lead":{"id":"h3","name":"Duren","skill":0.523,"inst":"fiddle"}},"renown":225,"season":{"wins":5,"bosses":0,"floors":5,"gold":0,"deaths":0,"fled":1,"pvp_wins":0,"pvp_losses":0,"renown":0,"days":30,"arguments":1},"career":{"wins":34,"bosses":2,"floors":23,"gold":0,"deaths":0,"fled":1,"pvp_wins":0,"pvp_losses":0,"renown":0,"days":90,"arguments":3},"former":[],"fallen":[],"travel":null,"wagon":{"kind":"donkey_cart","name":"The Ark","label":"donkey cart","seats":2,"haul":28,"comfort":1,"since":61,"desc":"Rattles. Gets there.","moves":true,"puller":{"kind":"donkey","name":"Bartholomew","label":"donkey","colour":"dun","owner":null},"paid":[["Duren",14],["Morwen",13],["Rook",12],["Gorm",7]]},"pace_gap":4,"rels":[{"party":"p4","score":100},{"party":"p1","score":100},{"party":"p6","score":100},{"party":"p2","score":19},{"party":"p5","score":1}],"events":[{"id":"e28","day":1,"season":1,"sday":1,"kind":"party_formed","imp":4,"text":"Duren and Rook shake on it at The Gilded Flagon: they are now The Azure Gravediggers. (Honorable, by the look of them.)","heroes":["h3","h15"],"parties":["p3"],"loc":"ironhaven","wx":"heat"},{"id":"e154","day":4,"season":1,"sday":4,"kind":"contract","imp":4,"text":"THE WALLS HELD. Raiders hit Ironhaven at midnight and The Azure Gravediggers were waiting. By dawn the town is ringing its bell in The Azure Gravediggers' honour.","heroes":["h3","h15","h5"],"parties":["p3"],"loc":"ironhaven","wx":"heat"},{"id":"e485","day":13,"season":1,"sday":13,"kind":"artifact","imp":5,"text":"Deep in Cragtooth Warren, Rook finds something with a name: the Ninth Ring. It has clearly been waiting for someone.","heroes":["h15"],"parties":["p3"],"loc":"cragtooth_warren"},{"id":"e490","day":13,"season":1,"sday":13,"kind":"rescue","imp":4,"text":"Brix (Griffin's hero) owes Duren (Sam's hero) a life now: The Azure Gravediggers pulled The Mercy of Thornwall out of trouble in Cragtooth Warren, 2 potions poorer.","heroes":["h3","h1","h15","h5","h9","h17","h11"],"parties":["p3","p4"],"loc":"cragtooth_warren","rescuers":["h3","h15","h5","h9"]},{"id":"e635","day":17,"season":1,"sday":17,"kind":"boss","imp":5,"text":"Two Drakes and the Mimic King have held the bottom of Cragtooth Warren long enough: the Azure Gravediggers bring them down. The last drake decides enough is enough, and goes. The Mimic King moved like it was wading after Rook's Cold Snap. Gorm's Judgement took most of the fight out of the Mimic King in one go. Gorm landed the hit that turned it, then went straight back to guarding the packs. Morwen's Ambush turned the fight. Duren never left the leader's side. Loot: 92 silver each, 2 gems, 12 trinkets.","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"cragtooth_warren","fight":"f75","foes":["mimic_king","drake","drake"],"where":"at the bottom of Cragtooth Warren","won":true,"close":false,"shape":"foe","reworded":-62},{"id":"e657","day":17,"season":1,"sday":17,"kind":"big_move","imp":4,"text":"Two Drakes and the Mimic King have held the bottom of Cragtooth Warren long enough: the Azure Gravediggers bring them down. On the table: Gorm +79 renown (14th to 7th), Morwen +77 (11th to 4th), Rook +76 (6th to 1st) and Duren +76 (10th to 3rd). The Azure Gravediggers +151 party renown (4th to 1st among the crews).","heroes":["h9","h5","h15","h3"],"parties":["p3"],"cause":"e635","moves":[{"hero":"h9","gain":79,"from":14,"to":7},{"hero":"h5","gain":77,"from":11,"to":4},{"hero":"h15","gain":76,"from":6,"to":1},{"hero":"h3","gain":76,"from":10,"to":3}],"party_moves":[{"party":"p3","gain":151,"from":4,"to":1}],"fight":"f75"},{"id":"e754","day":20,"season":1,"sday":20,"kind":"talent","imp":2,"text":"A Carrbridge card cheat gives up the moment Duren points across the room. It turns out pointing is enough. Mark of the Oath: one of the things Duren learned the long way round.","heroes":["h3"],"parties":["p3"],"loc":"carrbridge","skill":"mark_of_the_oath"},{"id":"e759","day":20,"season":1,"sday":20,"kind":"talent","imp":1,"text":"A queue forms at the Carrbridge temple when word gets out Gorm is inside. He sees every single one. (Living Saint, if anyone's asking.)","heroes":["h9"],"parties":["p3"],"loc":"carrbridge","skill":"living_saint"},{"id":"e794","day":21,"season":1,"sday":21,"kind":"talent","imp":1,"text":"Morwen sells a haunch of venison to an Ashfen innkeeper, who asks for another by the end of the week. Game Hunter: a ranger's patience, mostly.","heroes":["h5"],"parties":["p3"],"loc":"ashfen","skill":"game_hunter","wx":"rain"},{"id":"e825","day":22,"season":1,"sday":22,"kind":"talent","imp":1,"text":"Rook mutters the word over supper and every knot in camp comes undone, Duren's bootlaces included. That's The Unravelling Word for you.","heroes":["h15","h3"],"parties":["p3"],"loc":"ashveil_crypts","skill":"unravelling_word","wx":"rain"},{"id":"e857","day":23,"season":1,"sday":23,"kind":"delve","imp":1,"text":"The Azure Gravediggers descend into the Ashveil Crypts, mostly explored (66%).","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"ashveil_crypts","wx":"rain"},{"id":"e858","day":23,"season":1,"sday":23,"kind":"fight","imp":1,"text":"Rook hits hardest as the Azure Gravediggers beat 2 Skeletons and a Giant Rat on floor 1 of the Ashveil Crypts. Everything after Rook's Unravelling Word went right. Loot: 6 bones, 2 crypt-caps.","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"ashveil_crypts","fight":"f89","foes":["skeleton","skeleton","giant_rat"],"where":"on floor 1 of The Ashveil Crypts","won":true,"close":false,"shape":"hero","reworded":-21,"wx":"rain"},{"id":"e859","day":23,"season":1,"sday":23,"kind":"talent","imp":1,"text":"Duren says a quiet grace over the fire. Rook bows too, a beat late. The words of Devout, half under their breath.","heroes":["h3","h15"],"parties":["p3"],"loc":"ashveil_crypts","skill":"devout","wx":"rain"},{"id":"e866","day":23,"season":1,"sday":23,"kind":"meet","imp":2,"text":"Duren and Bramble swap stories in the Ashveil Crypts while The Azure Gravediggers and The Newts of Ashfen swap rumours.","heroes":["h3","h15","h5","h9","h13","h7"],"parties":["p3","p1"],"loc":"ashveil_crypts","wx":"rain"},{"id":"e870","day":23,"season":1,"sday":23,"kind":"talent","imp":1,"text":"Something undead takes one look at Gorm and falls over on its own.","heroes":["h9"],"parties":["p3"],"loc":"ashveil_crypts","skill":"living_saint","wx":"rain"},{"id":"e881","day":24,"season":1,"sday":24,"kind":"fight","imp":3,"text":"Floor 2 of the Ashveil Crypts turns up 2 Skeletons and Risen Dead, and the Azure Gravediggers see them off. One Smite from Gorm, and the skeleton stopped being a problem. Duren's Oath of Light turned the fight. Loot: 5 bones, 2 crypt-caps.","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"ashveil_crypts","fight":"f90","foes":["zombie","skeleton","skeleton"],"where":"on floor 2 of The Ashveil Crypts","won":true,"close":false,"shape":"place","reworded":-16,"wx":"rain"},{"id":"e882","day":24,"season":1,"sday":24,"kind":"night","imp":1,"text":"Something small and clever gets into The Azure Gravediggers' camp in the Ashveil Crypts overnight. Duren wakes up 3 silver and 2 rations lighter.","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"ashveil_crypts","wx":"rain"},{"id":"e892","day":24,"season":1,"sday":24,"kind":"talent","imp":2,"text":"Morwen finds moonpetal growing in a crack at the Ashveil Crypts, glowing faintly. It's worth more than the fight was.","heroes":["h5"],"parties":["p3"],"loc":"ashveil_crypts","skill":"herbalism","wx":"rain"},{"id":"e896","day":24,"season":1,"sday":24,"kind":"talent","imp":1,"text":"Duren wakes up with an old ache gone and Gorm pretending to be asleep.","heroes":["h9","h3"],"parties":["p3"],"loc":"ashveil_crypts","skill":"living_saint","wx":"rain"},{"id":"e909","day":25,"season":1,"sday":25,"kind":"treasure","imp":1,"text":"Behind a loose stone on floor 3 of the Ashveil Crypts, Morwen finds 42 silver and a gem.","heroes":["h5","h3","h15","h9"],"parties":["p3"],"loc":"ashveil_crypts","wx":"rain"},{"id":"e910","day":25,"season":1,"sday":25,"kind":"talent","imp":1,"text":"Duren teaches Morwen to call a target in one word. Morwen picks 'that'.","heroes":["h3","h5"],"parties":["p3"],"loc":"ashveil_crypts","skill":"mark_of_the_oath","wx":"rain"},{"id":"e911","day":25,"season":1,"sday":25,"kind":"night","imp":1,"text":"A carter with a broken wheel in the Ashveil Crypts pays for The Azure Gravediggers' help in gossip: the deep rooms of Cragtooth Warren are open again.","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"ashveil_crypts","wx":"rain"},{"id":"e917","day":25,"season":1,"sday":25,"kind":"bond","imp":3,"text":"The Azure Gravediggers and The Black Vanguard are rivals now, starting with Morwen and Hazel.","heroes":["h5","h8"],"parties":["p3","p5"],"bond":"rivals"},{"id":"e919","day":25,"season":1,"sday":25,"kind":"meet","imp":1,"text":"The Mercy of Thornwall runs into The Azure Gravediggers in the Ashveil Crypts. Stories are exchanged, most of them exaggerated.","heroes":["h17","h11","h1","h3","h15","h5","h9"],"parties":["p4","p3"],"loc":"ashveil_crypts","wx":"rain"},{"id":"e925","day":25,"season":1,"sday":25,"kind":"talent","imp":1,"text":"Gorm lays out his pilgrim tokens by the fire and tells Morwen where each one came from. One quiet Pilgrim, and done.","heroes":["h9","h5"],"parties":["p3"],"loc":"ashveil_crypts","skill":"pilgrim","wx":"rain"},{"id":"e946","day":26,"season":1,"sday":26,"kind":"sniped","imp":3,"text":"Deep in the Ashveil Crypts, The Azure Gravediggers hear the roaring below stop. The Newts of Ashfen have reached Vessimir the Unburied first. The Azure Gravediggers stay and work the floors that are left.","heroes":["h3","h15","h5","h9","h13","h7"],"parties":["p3","p1"],"loc":"ashveil_crypts","snipers":["h13","h7"],"where":"inside","boss":"Vessimir the Unburied","in_fight":"f102","wx":"rain"},{"id":"e953","day":26,"season":1,"sday":26,"kind":"delve_done","imp":3,"text":"The Azure Gravediggers come up after 4 days in the Ashveil Crypts. They got down to floor 3, mapped 26% of it, disarmed 2 traps and came away with 37 silver between them. No boss, but the place paid. Counting everyone's digging, the Ashveil Crypts is picked clean (99%).","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"ashveil_crypts","days":4,"bottom":false,"rooms":[],"gold":37,"wx":"rain"},{"id":"e996","day":27,"season":1,"sday":27,"kind":"music","imp":2,"text":"\"Salt on the Wind\" is The Azure Gravediggers' anthem now, and they sing it like they wrote it.","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"ashfen","anthem":"salt_on_the_wind","night":"n46","wx":"rain"},{"id":"e1041","day":28,"season":1,"sday":28,"kind":"ability","imp":2,"text":"Morwen stops the party by a stream, wades in, and comes out with supper and a sprig of moonpetal. Duren has stopped asking how.","heroes":["h5","h3"],"parties":["p3"],"loc":"bleakmarsh","skill":"forest_larder","sk":"Forest Larder","rule":true,"wx":"rain"},{"id":"e1063","day":29,"season":1,"sday":29,"kind":"talent","imp":2,"text":"Rook drizzles wild honey over the porridge. Gorm looks at Rook as if Rook invented joy.","heroes":["h15","h9"],"parties":["p3"],"loc":"thornmere_ruins","skill":"honey_finder","wx":"rain"},{"id":"e1070","day":29,"season":1,"sday":29,"kind":"boss_race","imp":3,"text":"Word in the taverns: The Newts of Ashfen, The Azure Gravediggers and The Mercy of Thornwall are all after Mother Thornmere. Thornmere Ruins has one way down and room for one winner.","heroes":["h13","h7","h3","h15","h5","h9","h17","h11","h1"],"parties":["p1","p3","p4"],"loc":"thornmere_ruins","wx":"rain"},{"id":"e1092","day":30,"season":1,"sday":30,"kind":"delve","imp":1,"text":"The Azure Gravediggers descend into Thornmere Ruins, mostly unexplored (23%).","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"thornmere_ruins","wx":"rain"},{"id":"e1093","day":30,"season":1,"sday":30,"kind":"fight","imp":2,"text":"The Azure Gravediggers see off 3 Swamp Trolls and a Will-o'-Wisp on floor 1 of Thornmere Ruins without much fuss. Before Gorm's Smite it could have gone either way. Loot: 26 silver each, 2 bottled wisplight, 2 wisp sugar.","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"thornmere_ruins","fight":"f106","foes":["wisp","swamp_troll","swamp_troll"],"where":"on floor 1 of Thornmere Ruins","won":true,"close":false,"shape":"plain","reworded":-18,"wx":"rain"},{"id":"e1102","day":30,"season":1,"sday":30,"kind":"talent","imp":1,"text":"Rook runs a hand over a pile of junk and pulls out the one candlestick that hums. Into the pack it goes. A small Detect Magic, cast without looking up.","heroes":["h15"],"parties":["p3"],"loc":"thornmere_ruins","skill":"detect_magic","wx":"rain"},{"id":"e1112","day":30,"season":1,"sday":30,"kind":"delve_done","imp":1,"text":"The Azure Gravediggers come up after 1 day in Thornmere Ruins. They got down to floor 1, mapped 8% of it and came away with 104 silver between them. Counting everyone's digging, Thornmere Ruins is mostly unexplored (24%).","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"thornmere_ruins","days":1,"bottom":false,"rooms":[],"gold":104,"wx":"rain"},{"id":"e1113","day":30,"season":1,"sday":30,"kind":"talent","imp":1,"text":"Morwen brews a tea from three leaves Rook has never noticed. Everyone sleeps beautifully.","heroes":["h5","h15"],"parties":["p3"],"loc":"thornmere_ruins","skill":"forest_larder","wx":"rain"},{"id":"e1119","day":30,"season":1,"sday":30,"kind":"goal_done","imp":4,"text":"GOAL: The Azure Gravediggers set out to finish the season as one of the top three parties, and the final table says they made it. XP: Duren +960 (level 13!), Rook +848 (level 13!), Morwen +800 (level 13!), Gorm +960 (level 13!).","heroes":[],"parties":["p3"],"xp":{"h3":960,"h15":848,"h5":800,"h9":960}},{"id":"e1143","day":31,"season":2,"sday":1,"kind":"map_bought","imp":2,"text":"The Azure Gravediggers buy a map of the Ashveil Crypts in Ashfen for 28 silver, drawn by Isolde. The place is partly explored (44%).","heroes":["h3","h15","h5","h9","h18"],"parties":["p3"],"loc":"ashfen"},{"id":"e1152","day":31,"season":2,"sday":1,"kind":"boss_race","imp":3,"text":"Word in the taverns: The Newts of Ashfen and The Azure Gravediggers are both after Vessimir the Unburied's Avenger. The Ashveil Crypts has one way down and room for one winner.","heroes":["h13","h7","h3","h15","h5","h9"],"parties":["p1","p3"],"loc":"ashveil_crypts"},{"id":"e1154","day":31,"season":2,"sday":1,"kind":"meet","imp":2,"text":"Duren and Vex swap stories in the Ashveil Crypts while The Azure Gravediggers and The Newts of Ashfen swap rumours.","heroes":["h3","h15","h5","h9","h13","h7"],"parties":["p3","p1"],"loc":"ashveil_crypts"},{"id":"e1155","day":31,"season":2,"sday":1,"kind":"journey","imp":2,"text":"The Newts of Ashfen and The Azure Gravediggers share the road to the Ashveil Crypts. By the second milestone they've agreed on nothing, least of all what they'd do if they retired.","heroes":["h13","h7","h3","h15","h5","h9"],"parties":["p1","p3"]},{"id":"e1164","day":31,"season":2,"sday":1,"kind":"campfire","imp":1,"text":"A month in The Azure Gravediggers together. Duren and Rook know each other's snores, sorrows and orders by heart.","heroes":["h3","h15"],"parties":["p3"],"loc":"ashveil_crypts"},{"id":"e1184","day":32,"season":2,"sday":2,"kind":"delve","imp":1,"text":"The Azure Gravediggers descend into the Ashveil Crypts, partly explored (44%), map in hand.","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"ashveil_crypts"},{"id":"e1185","day":32,"season":2,"sday":2,"kind":"fight","imp":2,"text":"Three Skeletons and a Giant Rat are waiting on floor 1 of the Ashveil Crypts, and the Azure Gravediggers see them off. Morwen's Thorn Whip took most of the fight out of the skeleton in one go. Loot: a rat haunch, 10 bones, 4 crypt-caps.","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"ashveil_crypts","fight":"f111","foes":["giant_rat","skeleton","skeleton"],"where":"on floor 1 of The Ashveil Crypts","won":true,"close":false,"shape":"foe","reworded":-26},{"id":"e1197","day":32,"season":2,"sday":2,"kind":"talent","imp":2,"text":"Duren points their mace at the biggest thing in the room. The party knows the drill. Somebody asks how. 'Mark of the Oath,' says Duren.","heroes":["h3"],"parties":["p3"],"loc":"ashveil_crypts","skill":"mark_of_the_oath"},{"id":"e1201","day":32,"season":2,"sday":2,"kind":"campfire","imp":3,"text":"A month in The Azure Gravediggers: Duren could pick Morwen's footsteps out of a crowd now.","heroes":["h3","h5"],"parties":["p3"],"loc":"ashveil_crypts"},{"id":"e1202","day":32,"season":2,"sday":2,"kind":"campfire","imp":1,"text":"Rook and Morwen have a month of roads behind them in The Azure Gravediggers, and a dozen stories nobody else is allowed to tell.","heroes":["h15","h5"],"parties":["p3"],"loc":"ashveil_crypts"},{"id":"e1212","day":33,"season":2,"sday":3,"kind":"fight","imp":1,"text":"The Azure Gravediggers, in fine spirits lately, beat Risen Dead, a Skeleton and a Skeleton Archer on floor 2 of the Ashveil Crypts. Duren ended it with Mark of the Oath. Rook pulled a friend out of trouble and went back in for more. Loot: 2 grave dust, 2 remains, 6 bones.","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"ashveil_crypts","fight":"f115","foes":["zombie","skeleton","skeleton_archer"],"where":"on floor 2 of The Ashveil Crypts","won":true,"close":false,"shape":"mood","reworded":-25},{"id":"e1249","day":34,"season":2,"sday":4,"kind":"fight","imp":1,"text":"With Gorm hitting hardest, the Azure Gravediggers cut down 2 Skeleton Archers and Risen Dead on floor 3 of the Ashveil Crypts. One Judgement from Gorm, and the risen dead stopped being a problem. Loot: 7 bones, 3 grave dust, 2 remains.","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"ashveil_crypts","fight":"f120","foes":["skeleton_archer","zombie","skeleton_archer"],"where":"on floor 3 of The Ashveil Crypts","won":true,"close":false,"shape":"hero","reworded":-27,"wx":"storm"},{"id":"e1278","day":35,"season":2,"sday":5,"kind":"fight","imp":2,"text":"On floor 4 of the Ashveil Crypts, the Azure Gravediggers make short work of 2 Bone Constructs and 2 Wraiths. Rook sent Arcane Torrent across the fight. The wraith didn't come back from it. Loot: 27 bones, 3 crypt-caps, 6 ectoplasm.","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"ashveil_crypts","fight":"f123","foes":["bone_construct","wraith","wraith"],"where":"on floor 4 of The Ashveil Crypts","won":true,"close":false,"shape":"place","reworded":-1,"wx":"storm"},{"id":"e1291","day":35,"season":2,"sday":5,"kind":"campfire","imp":2,"text":"A month in The Azure Gravediggers: Duren could pick Gorm's footsteps out of a crowd now.","heroes":["h3","h9"],"parties":["p3"],"loc":"ashveil_crypts","wx":"storm"},{"id":"e1292","day":35,"season":2,"sday":5,"kind":"campfire","imp":1,"text":"Rook and Gorm see in a month of The Azure Gravediggers by splitting the last good bottle. Nobody else is offered any.","heroes":["h15","h9"],"parties":["p3"],"loc":"ashveil_crypts","wx":"storm"},{"id":"e1293","day":35,"season":2,"sday":5,"kind":"campfire","imp":1,"text":"Morwen and Gorm have a month of roads behind them in The Azure Gravediggers, and a dozen stories nobody else is allowed to tell.","heroes":["h5","h9"],"parties":["p3"],"loc":"ashveil_crypts","wx":"storm"},{"id":"e1315","day":36,"season":2,"sday":6,"kind":"boss","imp":5,"text":"The Azure Gravediggers slay Vessimir the Unburied's Avenger, a Wraith and a Bone Construct at the bottom of the Ashveil Crypts and live to tell of it. The bone construct had been trouble right up until Gorm's Judgement. Everyone fought a little better after Duren's Oath of Light. Morwen's Ambush kicked in when it counted. Rook was everywhere at once. Loot: 135 silver each, 8 ectoplasm, 13 grave dust.","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"ashveil_crypts","fight":"f128","foes":["necromancer","wraith","bone_construct"],"where":"at the bottom of The Ashveil Crypts","won":true,"close":false,"shape":"plain","reworded":-23,"wx":"fog"},{"id":"e1316","day":36,"season":2,"sday":6,"kind":"treasure","imp":2,"text":"Vessimir the Unburied's Avenger's hoard, counted twice by torchlight: 15 gold pieces and 2 silver.","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"ashveil_crypts","in_fight":"f128","wx":"fog"},{"id":"e1317","day":36,"season":2,"sday":6,"kind":"rivalry","imp":4,"text":"Payback. The Azure Gravediggers beat The Newts of Ashfen to a boss at last. Somebody buys a round and makes sure The Newts of Ashfen hear about it.","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"ashveil_crypts","in_fight":"f128","wx":"fog"},{"id":"e1318","day":36,"season":2,"sday":6,"kind":"sniped","imp":3,"text":"Deep in the Ashveil Crypts, The Newts of Ashfen hear the roaring below stop. The Azure Gravediggers have reached Vessimir the Unburied's Avenger first. The Newts of Ashfen stay and work the floors that are left.","heroes":["h13","h7","h3","h15","h5","h9"],"parties":["p1","p3"],"loc":"ashveil_crypts","snipers":["h3","h15","h5","h9"],"where":"inside","boss":"Vessimir the Unburied's Avenger","in_fight":"f128","wx":"fog"},{"id":"e1319","day":36,"season":2,"sday":6,"kind":"race_won","imp":3,"text":"The Azure Gravediggers win the race to Vessimir the Unburied's Avenger, ahead of The Newts of Ashfen. The bets are paid out in Ashfen before the blood is dry.","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"ashveil_crypts","in_fight":"f128","wx":"fog"},{"id":"e1340","day":36,"season":2,"sday":6,"kind":"big_move","imp":4,"text":"The Azure Gravediggers slay Vessimir the Unburied's Avenger, a Wraith and a Bone Construct at the bottom of the Ashveil Crypts and live to tell of it. On the table: Rook +110 renown (6th to 1st), Gorm +108 (5th to 2nd), Duren +107 (12th to 4th) and Morwen +100 (7th to 3rd). The Azure Gravediggers +193 party renown (2nd to 1st among the crews).","heroes":["h15","h9","h3","h5"],"parties":["p3"],"cause":"e1315","moves":[{"hero":"h15","gain":110,"from":6,"to":1},{"hero":"h9","gain":108,"from":5,"to":2},{"hero":"h3","gain":107,"from":12,"to":4},{"hero":"h5","gain":100,"from":7,"to":3}],"party_moves":[{"party":"p3","gain":193,"from":2,"to":1}],"fight":"f128"},{"id":"e1345","day":37,"season":2,"sday":7,"kind":"treasure","imp":1,"text":"Morwen insists on checking one more passage on floor 4 of the Ashveil Crypts, and it opens onto a collapsed side passage: 4 gold pieces, 4 silver and a crypt-cap.","heroes":["h5","h3","h15","h9"],"parties":["p3"],"loc":"ashveil_crypts"},{"id":"e1346","day":37,"season":2,"sday":7,"kind":"talent","imp":1,"text":"Morwen brews something green and bitter for Duren's cough. Duren hates it. The cough's gone by morning.","heroes":["h5","h3"],"parties":["p3"],"loc":"ashveil_crypts","skill":"herbalism"},{"id":"e1379","day":38,"season":2,"sday":8,"kind":"fight","imp":1,"text":"The Azure Gravediggers dispatch a Wraith on floor 4 of the Ashveil Crypts, again. Duren finished the wraith with Mark of the Oath and leaned on their weapon, breathing hard. Loot: 2 ectoplasm.","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"ashveil_crypts","fight":"f132","foes":["wraith"],"where":"on floor 4 of The Ashveil Crypts","won":true,"close":false,"shape":"again","reworded":-7},{"id":"e1413","day":39,"season":2,"sday":9,"kind":"delve_done","imp":1,"text":"The Azure Gravediggers come up after 8 days in the Ashveil Crypts. They got all the way to the bottom, mapped 100% of it, found a collapsed side passage and came away with 752 silver between them. Counting everyone's digging, the Ashveil Crypts is picked clean (99%).","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"ashveil_crypts","days":8,"bottom":true,"rooms":["a collapsed side passage"],"gold":752},{"id":"e1442","day":40,"season":2,"sday":10,"kind":"road","imp":3,"text":"Morwen learns from the tinkers how to mend a pot with a spoon and a prayer. The pot holds, which is mostly the prayer.","heroes":["h5","h15","h3","h9"],"parties":["p3"],"road":"ashfen~ashveil_crypts","traveller":"kettleby","road_rec":"r269"},{"id":"e1489","day":41,"season":2,"sday":11,"kind":"goal","imp":2,"text":"After a long night's talk, The Azure Gravediggers settle on a goal: to bring down The Mimic King's Ghost in Cragtooth Warren.","heroes":["h3","h15","h5"],"parties":["p3"]},{"id":"e1532","day":43,"season":2,"sday":13,"kind":"delve","imp":1,"text":"The Azure Gravediggers descend into Thornmere Ruins, partly explored (47%).","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"thornmere_ruins"},{"id":"e1533","day":43,"season":2,"sday":13,"kind":"fight","imp":3,"text":"The Azure Gravediggers, in fine spirits lately, see off 2 Will-o'-Wisps and a Swamp Troll on floor 1 of Thornmere Ruins. The swamp troll took Rook's Unravelling Word full on and was never the same after. Rook kept two of them busy so nobody else had to. Loot: 4 silver each, 2 bottled wisplight.","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"thornmere_ruins","fight":"f150","foes":["swamp_troll","wisp","wisp"],"where":"on floor 1 of Thornmere Ruins","won":true,"close":false,"shape":"mood","reworded":-25},{"id":"e1561","day":44,"season":2,"sday":14,"kind":"fight","imp":3,"text":"It's 3 Drakes and a Will-o'-Wisp against the Azure Gravediggers on floor 2 of Thornmere Ruins, and it isn't close. Once Rook's Annotated Bolt was on the drake, the rest was arithmetic. Ask the others what won it: Gorm's Battle Cry. Loot: 3 drake scales, 11 fangs & claws, 4 drake flanks.","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"thornmere_ruins","fight":"f154","foes":["drake","wisp","drake"],"where":"on floor 2 of Thornmere Ruins","won":true,"close":false,"shape":"foe","reworded":-28},{"id":"e1562","day":44,"season":2,"sday":14,"kind":"treasure","imp":1,"text":"Duren jimmies open a chest on floor 2 of Thornmere Ruins: 51 silver.","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"thornmere_ruins"},{"id":"e1576","day":44,"season":2,"sday":14,"kind":"meet","imp":2,"text":"The Azure Gravediggers warn The Newts of Ashfen about what's lurking in Thornmere Ruins. The Newts of Ashfen pretend to already know.","heroes":["h3","h15","h5","h9","h13","h7"],"parties":["p3","p1"],"loc":"thornmere_ruins"},{"id":"e1584","day":44,"season":2,"sday":14,"kind":"campfire","imp":1,"text":"Rook admits to being afraid of the dark. Duren doesn't laugh. Duren just nods and takes the watch nearest it.","heroes":["h3","h15"],"parties":["p3"],"loc":"thornmere_ruins"},{"id":"e1589","day":44,"season":2,"sday":14,"kind":"ledger","imp":2,"text":"The week's trade: 14 packs emptied onto counters for 799 silver. Biggest haul: Vex, 126 silver in Ashfen. Back up from the deep: The Green Mercy (3 days in the Sunken Vault), The Azure Gravediggers (8 days in the Ashveil Crypts), The Mercy of Thornwall (4 days in the Wolf Den).","heroes":["h7","h19","h3","h17"],"parties":["p6","p3","p4"]},{"id":"e1592","day":45,"season":2,"sday":15,"kind":"fight","imp":1,"text":"On floor 2 of Thornmere Ruins, 2 Drakes get in the Azure Gravediggers' way, briefly. The last drake bolts. Everyone fought a little better after Duren's Oath of Light. Loot: 2 fangs & claws, 2 drake flanks.","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"thornmere_ruins","fight":"f159","foes":["drake","drake"],"where":"on floor 2 of Thornmere Ruins","won":true,"close":false,"shape":"place","reworded":-13},{"id":"e1620","day":46,"season":2,"sday":16,"kind":"fight","imp":1,"text":"The Azure Gravediggers cut down a Siren on floor 3 of Thornmere Ruins. The final blow was Rook's Unravelling Word. Loot: 1 gem, 2 trinkets.","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"thornmere_ruins","fight":"f167","foes":["siren"],"where":"on floor 3 of Thornmere Ruins","won":true,"close":false,"shape":"plain"},{"id":"e1621","day":46,"season":2,"sday":16,"kind":"artifact","imp":3,"text":"Duren pockets a purse that is always a little fuller than it should be in Thornmere Ruins. Duren feels stronger already.","heroes":["h3"],"parties":["p3"],"loc":"thornmere_ruins"},{"id":"e1629","day":46,"season":2,"sday":16,"kind":"sniped","imp":3,"text":"Deep in Thornmere Ruins, The Azure Gravediggers hear the roaring below stop. Amber Banner has reached Mother Thornmere first. The Azure Gravediggers stay and work the floors that are left.","heroes":["h3","h15","h5","h9","h18","h4","h2"],"parties":["p3","p2"],"loc":"thornmere_ruins","snipers":["h18","h4","h2"],"where":"inside","boss":"Mother Thornmere","in_fight":"f168"},{"id":"e1652","day":47,"season":2,"sday":17,"kind":"fight","imp":1,"text":"Morwen hits hardest as the Azure Gravediggers see off 2 Drakes on floor 4 of Thornmere Ruins. Morwen put Thorn Whip into the drake to end it, and lowered the bow. Loot: 2 drake scales, 2 drake flanks, 2 fangs & claws.","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"thornmere_ruins","fight":"f169","foes":["drake","drake"],"where":"on floor 4 of Thornmere Ruins","won":true,"close":false,"shape":"hero","reworded":-23},{"id":"e1671","day":48,"season":2,"sday":18,"kind":"treasure","imp":2,"text":"Behind a forgotten storeroom on floor 4 of Thornmere Ruins, nobody had been in years. Rook comes out with 47 silver.","heroes":["h15","h3","h5","h9"],"parties":["p3"],"loc":"thornmere_ruins"},{"id":"e1685","day":48,"season":2,"sday":18,"kind":"argument","imp":3,"text":"Gorm and Morwen are not speaking. It's about who lost the map. It's never really about who lost the map.","heroes":["h9","h5"],"parties":["p3"]},{"id":"e1716","day":49,"season":2,"sday":19,"kind":"delve_done","imp":3,"text":"The Azure Gravediggers come up after 7 days in Thornmere Ruins. They got all the way to the bottom, mapped 71% of it, found a forgotten storeroom, disarmed 2 traps and came away with 108 silver between them. Amber Banner got the boss. The Azure Gravediggers got the rest. Counting everyone's digging, Thornmere Ruins is picked clean (99%).","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"thornmere_ruins","days":7,"bottom":true,"rooms":["a forgotten storeroom"],"gold":108},{"id":"e1728","day":50,"season":2,"sday":20,"kind":"curse","imp":4,"text":"Something is wrong with The Azure Gravediggers. Since Duren picked up the Red Purse, nobody trusts anybody, and Duren won't put it down.","heroes":["h3"],"parties":["p3"],"loc":"thornmere_ruins"},{"id":"e1747","day":50,"season":2,"sday":20,"kind":"ability","imp":2,"text":"Morwen wanders off the road for five minutes and comes back with mushrooms in their hat, hazelnuts in their pockets and a sprig of moonpetal behind their ear.","heroes":["h5"],"parties":["p3"],"loc":"bleakmarsh","skill":"forest_larder","sk":"Forest Larder","rule":true},{"id":"e1765","day":51,"season":2,"sday":21,"kind":"bounty","imp":2,"text":"The guild clerk in Carrbridge counts out bounties for The Azure Gravediggers until the cashbox is empty: 87 silver each.","heroes":["h3"],"parties":["p3"],"loc":"carrbridge","amount":87},{"id":"e1796","day":51,"season":2,"sday":21,"kind":"campfire","imp":2,"text":"Morwen lends Gorm a whetstone. It comes back cleaner than it left.","heroes":["h5","h9"],"parties":["p3"],"loc":"carrbridge"},{"id":"e1816","day":52,"season":2,"sday":22,"kind":"road","imp":3,"text":"Osk asks to see Duren's loot 'for the records', writes it all down and charges nothing, which is suspicious.","heroes":["h3","h15","h5","h9"],"parties":["p3"],"road":"carrbridge~ironhaven","traveller":"osk","road_rec":"r331"},{"id":"e1829","day":52,"season":2,"sday":22,"kind":"talent","imp":1,"text":"Duren sends a stew back at the Ironhaven tavern with notes. The cook comes out, listens, and returns with a better stew.","heroes":["h3"],"parties":["p3"],"loc":"ironhaven","skill":"camp_cook"},{"id":"e1838","day":52,"season":2,"sday":22,"kind":"talent","imp":2,"text":"Gorm visits the sick on three streets of Ironhaven before lunch and is sent off with a basket of eggs.","heroes":["h9"],"parties":["p3"],"loc":"ironhaven","skill":"house_calls"},{"id":"e1858","day":53,"season":2,"sday":23,"kind":"gift","imp":2,"text":"Nothing goes to waste in this crew: Rook's old Oilskin Cloak is Gorm's now.","heroes":["h15","h9"],"parties":["p3"],"loc":"ironhaven"},{"id":"e1861","day":53,"season":2,"sday":23,"kind":"road","imp":3,"text":"Rook turns Lady Perpetua Vane the right way round at last and walks her until the towers come into sight. She calls it 'a pleasant coincidence'.","heroes":["h15","h3","h5","h9"],"parties":["p3"],"road":"frosthold~ironhaven","traveller":"perpetua","road_rec":"r339"},{"id":"e1878","day":53,"season":2,"sday":23,"kind":"talent","imp":1,"text":"Morwen steps off the path for a moment and comes back with a hat full of mushrooms. Safe ones.","heroes":["h5"],"parties":["p3"],"loc":"ironhaven","skill":"forest_larder"},{"id":"e1889","day":53,"season":2,"sday":23,"kind":"goal_conceded","imp":3,"text":"The Azure Gravediggers hear the news about The Mimic King's Ghost and go quiet. The Mercy of Thornwall again. By evening there's a new goal on the table: to finish the season as one of the top three parties.","heroes":["h3","h15","h5","h9"],"parties":["p3"]},{"id":"e1904","day":54,"season":2,"sday":24,"kind":"boss_race","imp":3,"text":"Somebody chalks a tally on the board for the race to Hrimnir, Who Walks Under Snow: The Azure Gravediggers and Ottoline. Odds are offered, mostly on whoever's buying.","heroes":["h3","h15","h5","h9","h14"],"parties":["p3"],"loc":"frostspire"},{"id":"e1911","day":54,"season":2,"sday":24,"kind":"campfire","imp":1,"text":"Duren and Gorm share a rain cloak in a downpour and arrive soaked and laughing.","heroes":["h3","h9"],"parties":["p3"],"loc":"frosthold"},{"id":"e1929","day":55,"season":2,"sday":25,"kind":"party_life","imp":1,"text":"By the third crossroads Gorm has stopped waiting and started complaining about the wait.","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"frosthold"},{"id":"e1930","day":55,"season":2,"sday":25,"kind":"ambush","imp":2,"text":"The Azure Gravediggers, in fine spirits lately, make short work of 2 Frost Wolves and a Yeti at their camp in Whitepeak Pass, in the middle of the night. Rook landed Force Bolt on the yeti hard enough to hear from the back. Gorm kept them off everyone with Battle Cry. Rook kept the bleeding to a minimum. \"I'm fine. I'm fine. I'm not fine,\" says Rook. Loot: 11 pelts, 2 fangs & claws.","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"whitepeak","fight":"f187","foes":["frost_wolf","frost_wolf","yeti"],"where":"at their camp in Whitepeak Pass, in the middle of the night","won":true,"close":false,"shape":"mood","reworded":-25},{"id":"e1938","day":55,"season":2,"sday":25,"kind":"ability","imp":2,"text":"Morwen spots a patch of moonpetal on a sunny bank and picks one sprig, politely, leaving the rest to grow. The wild strawberries beside it are not treated so politely.","heroes":["h5"],"parties":["p3"],"loc":"whitepeak","skill":"forest_larder","sk":"Forest Larder","rule":true},{"id":"e1964","day":56,"season":2,"sday":26,"kind":"party_life","imp":1,"text":"Gorm waits at every crossroads for Duren, Rook and Morwen to catch up, and says nothing very loudly.","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"whitepeak"},{"id":"e1965","day":56,"season":2,"sday":26,"kind":"road","imp":2,"text":"Morwen finds the Snow Lamp low on oil and tops it up from their own flask, paying 2 copper to the tin for the trouble.","heroes":["h5","h15","h3","h9"],"parties":["p3"],"road":"frostspire~whitepeak","road_rec":"r368"},{"id":"e1976","day":56,"season":2,"sday":26,"kind":"meet","imp":2,"text":"The Azure Gravediggers and Ottoline share a fire in Frostspire. Nobody draws steel, which counts as a good meeting these days.","heroes":["h3","h15","h5","h9","h14"],"parties":["p3"],"loc":"frostspire"},{"id":"e1990","day":57,"season":2,"sday":27,"kind":"curse","imp":2,"text":"Duren snaps at a barkeep over nothing, then stares at the Red Purse for an hour. The curse is winning, for now.","heroes":["h3"],"parties":["p3"],"loc":"frostspire"},{"id":"e2002","day":57,"season":2,"sday":27,"kind":"delve","imp":1,"text":"The Azure Gravediggers descend into Frostspire, mostly unexplored (10%).","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"frostspire"},{"id":"e2003","day":57,"season":2,"sday":27,"kind":"fight","imp":2,"text":"On floor 1 of Frostspire, the Azure Gravediggers beat 3 Ice Wraiths, a Yeti and a Frost Wolf. The last frost wolf decides enough is enough, and goes. Three ice wraiths went down together, and they have Duren's Turn Undead to thank. Duren's Oath of Light kicked in when it counted. Loot: 9 ectoplasm, 4 frost crystals, 6 wraith-frost.","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"frostspire","fight":"f193","foes":["ice_wraith","ice_wraith","yeti"],"where":"on floor 1 of Frostspire","won":true,"close":false,"shape":"place","reworded":-30},{"id":"e2004","day":57,"season":2,"sday":27,"kind":"treasure","imp":3,"text":"Duren kicks over a rotten crate on floor 1 of Frostspire. Out rolls 115 silver, an Egg That Is Still Warm and a yeti steak.","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"frostspire"},{"id":"e2029","day":58,"season":2,"sday":28,"kind":"fight","imp":2,"text":"Four Frost Wolves and an Ice Wraith are waiting on floor 2 of Frostspire, and the Azure Gravediggers cut them down. Smite, from Gorm, was the last thing the frost wolf saw. Ambush came over Morwen at the right moment, as it does. Loot: 13 pelts, 13 fangs & claws, 8 wolf haunches.","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"frostspire","fight":"f197","foes":["frost_wolf","frost_wolf","frost_wolf"],"where":"on floor 2 of Frostspire","won":true,"close":false,"shape":"foe","reworded":-25},{"id":"e2040","day":58,"season":2,"sday":28,"kind":"meet","imp":1,"text":"Barnaby and Duren swap stories in Frostspire while The Green Mercy and The Azure Gravediggers swap rumours.","heroes":["h19","h20","h10","h16","h3","h15","h5","h9"],"parties":["p6","p3"],"loc":"frostspire"},{"id":"e2042","day":58,"season":2,"sday":28,"kind":"talent","imp":1,"text":"Gorm tells the story of how the Warchief's Horn changed hands. It has changed hands a lot.","heroes":["h9"],"parties":["p3"],"loc":"frostspire"},{"id":"e2053","day":59,"season":2,"sday":29,"kind":"fight","imp":2,"text":"The Azure Gravediggers beat 3 Frost Wolves and an Ice Wraith on floor 2 of Frostspire, again. Somewhere around Rook's Unravelling Word, the other side stopped believing. Battle Cry, from Gorm, at exactly the right moment. Loot: 12 pelts, 4 fangs & claws, 4 wolf haunches.","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"frostspire","fight":"f199","foes":["frost_wolf","frost_wolf","frost_wolf"],"where":"on floor 2 of Frostspire","won":true,"close":false,"shape":"again","reworded":-7},{"id":"e2054","day":59,"season":2,"sday":29,"kind":"treasure","imp":1,"text":"A dead adventurer on floor 2 of Frostspire won't be needing 580 silver, a gem and a wolf haunch any more. Gorm takes it, with thanks.","heroes":["h9","h3","h15","h5"],"parties":["p3"],"loc":"frostspire"},{"id":"e2075","day":59,"season":2,"sday":29,"kind":"talent","imp":2,"text":"Morwen lets Winter sleep across Rook's feet after a bad day. It does more good than any speech.","heroes":["h5","h15"],"parties":["p3"],"loc":"frostspire","skill":"kennel_keeper"},{"id":"e2102","day":60,"season":2,"sday":30,"kind":"fight","imp":2,"text":"Rook hits hardest as the Azure Gravediggers see off 2 Ice Golems and an Ice Wraith on floor 3 of Frostspire. The final blow was Gorm's Pan to the Face. Rook saved Rejuvenate for when it mattered. Loot: 4 frost crystals.","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"frostspire","fight":"f203","foes":["ice_golem","ice_golem","ice_wraith"],"where":"on floor 3 of Frostspire","won":true,"close":false,"shape":"hero","reworded":-21},{"id":"e2117","day":60,"season":2,"sday":30,"kind":"delve_done","imp":1,"text":"The Azure Gravediggers come up after 4 days in Frostspire. They got down to floor 3, mapped 30% of it, disarmed 1 trap and came away with 700 silver between them. Counting everyone's digging, Frostspire is partly explored (49%).","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"frostspire","days":4,"bottom":false,"rooms":[],"gold":700},{"id":"e2123","day":60,"season":2,"sday":30,"kind":"goal_done","imp":4,"text":"GOAL: The Azure Gravediggers set out to finish the season as one of the top three parties, and the final table says they made it. XP: Duren +800, Rook +880 (level 19!), Morwen +960, Gorm +800.","heroes":[],"parties":["p3"],"xp":{"h3":800,"h15":880,"h5":960,"h9":800}},{"id":"e2148","day":61,"season":3,"sday":1,"kind":"wagon","imp":3,"text":"The Azure Gravediggers buy a donkey cart in Hollowood for 46 silver. It's called The Ark now. Who paid: Duren 14, Morwen 13, Rook 12, Gorm 7.","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"hollowood","wx":"rain"},{"id":"e2149","day":61,"season":3,"sday":1,"kind":"bounty","imp":2,"text":"The guild clerk in Thornwall counts out bounties for The Azure Gravediggers until the cashbox is empty: 64 silver each.","heroes":["h3"],"parties":["p3"],"loc":"thornwall","amount":64},{"id":"e2190","day":62,"season":3,"sday":2,"kind":"curse","imp":5,"text":"Morwen has had enough. One night Morwen prises the Red Purse out of Duren's grip and buries it at a crossroads. Duren weeps, then sleeps for the first time in weeks.","heroes":["h3"],"parties":["p3"],"loc":"thornwall"},{"id":"e2195","day":62,"season":3,"sday":2,"kind":"road","imp":3,"text":"Morwen shows Pim the proper way to stand, hold a staff and watch a hedge. Pim learns fast and is pleased.","heroes":["h5","h15","h3","h9"],"parties":["p3"],"road":"carrbridge~thornwall","traveller":"pim","road_rec":"r417"},{"id":"e2230","day":63,"season":3,"sday":3,"kind":"night","imp":2,"text":"Morwen follows strange lights away from the camp in Bleakmarsh, gets thoroughly lost, and is found at dawn up a tree.","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"bleakmarsh","wx":"storm"},{"id":"e2239","day":63,"season":3,"sday":3,"kind":"bond","imp":3,"text":"The Azure Gravediggers and The Black Vanguard are rivals now, starting with Morwen and Ash.","heroes":["h5","h12"],"parties":["p3","p5"],"bond":"rivals"},{"id":"e2241","day":63,"season":3,"sday":3,"kind":"talent","imp":1,"text":"Gorm sings a walking hymn that matches the crew's pace exactly. The miles go by.","heroes":["h9"],"parties":["p3"],"loc":"bleakmarsh","skill":"hymn_singer","wx":"storm"},{"id":"e2246","day":63,"season":3,"sday":3,"kind":"campfire","imp":1,"text":"Winter the wolf won't sleep unless Rook is in sight. Nobody can explain it.","heroes":["h5","h15"],"parties":["p3"],"loc":"bleakmarsh","wx":"storm"},{"id":"e2251","day":64,"season":3,"sday":4,"kind":"fight","imp":2,"text":"The Azure Gravediggers dispatch 3 Bog Crawlers and a Swamp Troll in Bleakmarsh without much fuss. Morwen's Nature's Wrath put poison in the bog crawler, and it did its slow work. Duren's Oath of Light kicked in when it counted. Loot: 10 silver each, 12 chitin, 6 bog crawler claws.","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"bleakmarsh","fight":"f209","foes":["bog_crawler","swamp_troll","bog_crawler"],"where":"in Bleakmarsh","won":true,"close":false,"shape":"plain","reworded":-18,"wx":"storm"},{"id":"e2266","day":64,"season":3,"sday":4,"kind":"meet","imp":2,"text":"Amber Banner runs into The Azure Gravediggers in Bleakmarsh. Stories are exchanged, most of them exaggerated.","heroes":["h18","h4","h2","h3","h15","h5","h9"],"parties":["p2","p3"],"loc":"bleakmarsh","wx":"storm"},{"id":"e2269","day":64,"season":3,"sday":4,"kind":"campfire","imp":1,"text":"A wagon gets stuck on the road. Morwen and Rook push it out together and refuse the farmer's coin.","heroes":["h5","h15"],"parties":["p3"],"loc":"bleakmarsh","wx":"storm"},{"id":"e2293","day":65,"season":3,"sday":5,"kind":"campfire","imp":1,"text":"Rook carves Morwen's initials into the campfire log. Morwen carves a rude drawing next to them. Friendship.","heroes":["h15","h5"],"parties":["p3"],"loc":"bleakmarsh","wx":"storm"},{"id":"e2302","day":66,"season":3,"sday":6,"kind":"party_life","imp":3,"text":"Gorm rides ahead, rides back, rides ahead again. Morwen is not amused.","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"bleakmarsh","wx":"storm"},{"id":"e2320","day":66,"season":3,"sday":6,"kind":"talent","imp":2,"text":"Rook trades a jar of wild honey to a Carrbridge healer for a pouch of dried herbs.","heroes":["h15"],"parties":["p3"],"loc":"carrbridge","skill":"honey_finder"},{"id":"e2324","day":66,"season":3,"sday":6,"kind":"campfire","imp":1,"text":"Tofu the cat has chosen Duren. Duren pretends to mind. Rook is quietly delighted.","heroes":["h15","h3"],"parties":["p3"],"loc":"carrbridge"},{"id":"e2340","day":67,"season":3,"sday":7,"kind":"road","imp":3,"text":"A travelling menagerie fills the road to Ironhaven: a camel, three monkeys on a cart, a bear that waves and an elephant carrying the cook. Morwen walks beside it for an hour.","heroes":["h5","h15","h3","h9"],"parties":["p3"],"road":"carrbridge~ironhaven","road_rec":"r450"},{"id":"e2385","day":68,"season":3,"sday":8,"kind":"road","imp":2,"text":"Rook meets the Wet Boots Angling Club for the first time on the road to Frosthold, in a line along a ford with their trousers rolled to the knee and their lines in the water.","heroes":["h15","h3","h5","h9"],"parties":["p3"],"road":"frosthold~ironhaven","traveller":"wet_boots","road_rec":"r459"},{"id":"e2391","day":68,"season":3,"sday":8,"kind":"ability","imp":2,"text":"Morwen reads the hedgerows like a shop window. The party eats wild garlic and blackberries all afternoon, and Morwen pockets a sprig of moonpetal.","heroes":["h5"],"parties":["p3"],"loc":"ironhaven","skill":"forest_larder","sk":"Forest Larder","rule":true},{"id":"e2456","day":70,"season":3,"sday":10,"kind":"boss_race","imp":3,"text":"Somebody chalks a tally on the board for the race to Hrimnir, Who Walks Under Snow: The Azure Gravediggers, The Green Mercy and Ottoline. Odds are offered, mostly on whoever's buying.","heroes":["h3","h15","h5","h9","h19","h20","h10","h16","h14"],"parties":["p3","p6"],"loc":"frostspire","wx":"storm"},{"id":"e2459","day":70,"season":3,"sday":10,"kind":"meet","imp":2,"text":"The Azure Gravediggers and Ottoline share a fire in Whitepeak Pass. Duren shares a flask.","heroes":["h3","h15","h5","h9","h14"],"parties":["p3"],"loc":"whitepeak","wx":"storm"},{"id":"e2460","day":70,"season":3,"sday":10,"kind":"journey","imp":2,"text":"The Azure Gravediggers and The Green Mercy share the road to Whitepeak Pass. By the second milestone they've agreed on nothing, least of all the league table.","heroes":["h3","h15","h5","h9","h19","h20","h10","h16"],"parties":["p3","p6"]},{"id":"e2463","day":70,"season":3,"sday":10,"kind":"talent","imp":1,"text":"Rook knocks three times on a ruined arch near Whitepeak Pass and walks the crew through it, a day nearer than they were.","heroes":["h15"],"parties":["p3"],"loc":"whitepeak","skill":"portal_stone","wx":"storm"},{"id":"e2464","day":70,"season":3,"sday":10,"kind":"talent","imp":1,"text":"Duren follows a bee across a meadow to a hollow tree and returns with honeycomb and three stings. Honey Finder: a ranger's patience, mostly.","heroes":["h3"],"parties":["p3"],"loc":"whitepeak","skill":"honey_finder","wx":"storm"},{"id":"e2468","day":70,"season":3,"sday":10,"kind":"talent","imp":1,"text":"Morwen brings back a brace of rabbits and quietly gives Rook the best one.","heroes":["h5","h15"],"parties":["p3"],"loc":"whitepeak","skill":"game_hunter","wx":"storm"},{"id":"e2470","day":70,"season":3,"sday":10,"kind":"campfire","imp":1,"text":"Duren carves Gorm's initials into the campfire log. Gorm carves a rude drawing next to them. Friendship.","heroes":["h3","h9"],"parties":["p3"],"loc":"whitepeak","wx":"storm"},{"id":"e2493","day":71,"season":3,"sday":11,"kind":"road","imp":4,"text":"Osk has retired. A handshake for Duren, the words 'my favourite taxpayer', and off he goes, whistling.","heroes":["h3","h15","h5","h9"],"parties":["p3"],"road":"frostspire~whitepeak","traveller":"osk","road_rec":"r475"},{"id":"e2508","day":71,"season":3,"sday":11,"kind":"talent","imp":1,"text":"Gorm writes a letter home by firelight and reads out the funny bits. The crew adds a postscript each. Letter Writer, the guild calls it.","heroes":["h9"],"parties":["p3"],"loc":"frostspire","skill":"letter_writer","wx":"storm"},{"id":"e2513","day":71,"season":3,"sday":11,"kind":"goal","imp":2,"text":"The Azure Gravediggers set their sights for the season: to bring down Mother Thornmere's Brood in Thornmere Ruins.","heroes":["h3","h15","h5"],"parties":["p3"]},{"id":"e2528","day":72,"season":3,"sday":12,"kind":"delve","imp":1,"text":"The Azure Gravediggers descend into Frostspire, partly explored (51%), map in hand.","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"frostspire","wx":"storm"},{"id":"e2531","day":72,"season":3,"sday":12,"kind":"fight","imp":2,"text":"Two Ice Wraiths, a Yeti and a Frost Wolf are waiting on floor 1 of Frostspire, and the Azure Gravediggers cut them down. Gorm finished it with Judgement, barely looking. Ambush came over Morwen at the right moment, as it does. Loot: 1 frost crystal, 11 pelts, 3 ectoplasm.","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"frostspire","fight":"f240","foes":["ice_wraith","yeti","ice_wraith"],"where":"on floor 1 of Frostspire","won":true,"close":false,"shape":"foe","reworded":-24,"wx":"storm"},{"id":"e2548","day":72,"season":3,"sday":12,"kind":"argument","imp":2,"text":"It starts with which way the road went. It ends with Morwen and Duren sleeping on opposite sides of the fire.","heroes":["h5","h3"],"parties":["p3"]},{"id":"e2555","day":73,"season":3,"sday":13,"kind":"treasure","imp":1,"text":"Mapping floor 2 of Frostspire, Gorm finds a chamber of perfect frost carvings. Inside: 26 silver.","heroes":["h9","h3","h15","h5"],"parties":["p3"],"loc":"frostspire","wx":"snow"},{"id":"e2585","day":73,"season":3,"sday":13,"kind":"goal_conceded","imp":3,"text":"Amber Banner got to Mother Thornmere's Brood first. The Azure Gravediggers concede the season goal, mutters something about next time, and settle on a new one: to finish the season as one of the top three parties.","heroes":["h3","h15","h5","h9"],"parties":["p3"]},{"id":"e2605","day":74,"season":3,"sday":14,"kind":"fight","imp":3,"text":"On floor 2 of Frostspire, the Azure Gravediggers make short work of 2 Ice Wraiths, a Yeti and a Frost Wolf. Everything after Morwen's Nature's Wrath went right. Rook accounted for 4 of them, mostly with The Unravelling Word. Loot: 10 pelts, 2 fangs & claws, 6 ectoplasm.","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"frostspire","fight":"f246","foes":["yeti","frost_wolf","ice_wraith"],"where":"on floor 2 of Frostspire","won":true,"close":false,"shape":"place","reworded":-1,"wx":"snow"},{"id":"e2606","day":74,"season":3,"sday":14,"kind":"artifact","imp":3,"text":"Duren pockets a tin crown that tells its wearer who to distrust in Frostspire. Duren feels stronger already.","heroes":["h3"],"parties":["p3"],"loc":"frostspire","wx":"snow"},{"id":"e2620","day":74,"season":3,"sday":14,"kind":"talent","imp":1,"text":"Rook knows from a footnote that the third stair creaks. It does. Nobody steps on it.","heroes":["h15"],"parties":["p3"],"loc":"frostspire","skill":"seen_it_in_a_book","wx":"snow"},{"id":"e2647","day":75,"season":3,"sday":15,"kind":"fight","imp":2,"text":"The Azure Gravediggers, in fine spirits lately, beat 3 Ice Golems on floor 3 of Frostspire. Duren called the target with Mark of the Oath; the crew did the rest. Miracle, from Gorm, at exactly the right moment. Loot: 7 frost crystals, 9 glacier ice.","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"frostspire","fight":"f251","foes":["ice_golem","ice_golem","ice_golem"],"where":"on floor 3 of Frostspire","won":true,"close":false,"shape":"mood","reworded":-25,"wx":"snow"},{"id":"e2688","day":76,"season":3,"sday":16,"kind":"treasure","imp":3,"text":"Mapping floor 4 of Frostspire, Rook finds a collapsed side passage. Inside: 3 gold pieces, 48 silver and an old Bog-Warped Tarot.","heroes":["h15","h3","h5","h9"],"parties":["p3"],"loc":"frostspire","wx":"fog"},{"id":"e2692","day":76,"season":3,"sday":16,"kind":"sniped","imp":3,"text":"Deep in Frostspire, The Azure Gravediggers hear the roaring below stop. Ottoline has reached Hrimnir, Who Walks Under Snow first. The Azure Gravediggers stay and work the floors that are left.","heroes":["h3","h15","h5","h9","h14"],"parties":["p3"],"loc":"frostspire","snipers":["h14"],"where":"inside","boss":"Hrimnir, Who Walks Under Snow","in_fight":"f256","wx":"fog"},{"id":"e2728","day":77,"season":3,"sday":17,"kind":"treasure","imp":1,"text":"Behind an old adventurers' camp, abandoned in a hurry on floor 4 of Frostspire, nobody had been in years. Morwen comes out with 3 gold pieces, 3 silver and a block of glacier ice.","heroes":["h5","h3","h15","h9"],"parties":["p3"],"loc":"frostspire","wx":"fog"},{"id":"e2739","day":77,"season":3,"sday":17,"kind":"meet","imp":1,"text":"The Azure Gravediggers warn The Green Mercy about what's lurking in Frostspire. The Green Mercy pretends to already know.","heroes":["h3","h15","h5","h9","h19","h20","h10","h16"],"parties":["p3","p6"],"loc":"frostspire","wx":"fog"},{"id":"e2741","day":77,"season":3,"sday":17,"kind":"talent","imp":2,"text":"Rook says half the word at a rusted gate. The gate considers it and falls off its hinges.","heroes":["h15"],"parties":["p3"],"loc":"frostspire","skill":"unravelling_word","wx":"fog"},{"id":"e2748","day":77,"season":3,"sday":17,"kind":"campfire","imp":1,"text":"Rook and Morwen have a two-hour argument about whether a goblin could beat a goose. It is never resolved.","heroes":["h15","h5"],"parties":["p3"],"loc":"frostspire","wx":"fog"},{"id":"e2758","day":78,"season":3,"sday":18,"kind":"curse","imp":4,"text":"Something is wrong with The Azure Gravediggers. Since Duren picked up the Whispering Crown, nobody trusts anybody, and Duren won't put it down.","heroes":["h3"],"parties":["p3"],"loc":"frostspire","wx":"fog"},{"id":"e2772","day":78,"season":3,"sday":18,"kind":"delve_done","imp":3,"text":"The Azure Gravediggers come up after 7 days in Frostspire. They got all the way to the bottom, mapped 83% of it, found a chamber of perfect frost carvings, a collapsed side passage and an old adventurers' camp, abandoned in a hurry, disarmed 1 trap and came away with 132 silver between them. No boss, but the place paid. Counting everyone's digging, Frostspire is picked clean (99%).","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"frostspire","days":7,"bottom":true,"rooms":["a chamber of perfect frost carvings","a collapsed side passage"],"gold":132,"wx":"fog"},{"id":"e2779","day":78,"season":3,"sday":18,"kind":"talent","imp":1,"text":"Duren carries Gorm out on their back, the long way, and never once complains.","heroes":["h3","h9"],"parties":["p3"],"loc":"frostspire","skill":"shepherd_of_the_fallen","wx":"fog"},{"id":"e2791","day":79,"season":3,"sday":19,"kind":"night","imp":2,"text":"A grey dwarf shares The Azure Gravediggers' fire in Whitepeak Pass and swears on his beard there's a room in Goblin Camp nobody has opened. There isn't much beard left.","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"whitepeak","wx":"fog"},{"id":"e2811","day":79,"season":3,"sday":19,"kind":"campfire","imp":1,"text":"Rook and Duren make a list of every tavern that has thrown them out. It's longer than expected.","heroes":["h15","h3"],"parties":["p3"],"loc":"whitepeak","wx":"fog"},{"id":"e2831","day":80,"season":3,"sday":20,"kind":"road","imp":3,"text":"A well beside the road to Frosthold is rumoured to bless whoever drinks at dawn. Duren drinks, and feels nothing, then discovers a day later that all their blisters have gone.","heroes":["h3","h15","h5","h9"],"parties":["p3"],"road":"frosthold~whitepeak","road_rec":"r520"},{"id":"e2843","day":80,"season":3,"sday":20,"kind":"journey","imp":2,"text":"The Green Mercy and The Azure Gravediggers fall in together on the road to Frosthold and spend the miles arguing about the best way to cook a rat.","heroes":["h19","h20","h10","h16","h3","h15","h5","h9"],"parties":["p6","p3"]},{"id":"e2881","day":81,"season":3,"sday":21,"kind":"talent","imp":2,"text":"Duren throws a double six at the Veldrock tavern to win a bet nobody else would take. Dice Luck, the guild calls it.","heroes":["h3"],"parties":["p3"],"loc":"veldrock","skill":"dice_luck","wx":"fog"},{"id":"e2884","day":81,"season":3,"sday":21,"kind":"talent","imp":1,"text":"Morwen sells a bundle of wild herbs to the Veldrock apothecary for a fair price. That's Forest Larder for you.","heroes":["h5"],"parties":["p3"],"loc":"veldrock","skill":"forest_larder","wx":"fog"},{"id":"e2905","day":82,"season":3,"sday":22,"kind":"ambush","imp":3,"text":"The Azure Gravediggers defeat 2 Bandits and 2 Bandit Captains on the road to Emberdeep. The last bandit breaks and runs. Rook cast Unravelling Word, and the bandit did not get up. Without Duren's Oath of Light, this goes differently. Gorm picked the biggest one and did not regret it. \"Fine,\" says Gorm. Loot: 38 silver each, 15 stolen goods, 1 gem.","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"kingsroad","fight":"f264","foes":["bandit","bandit_captain","bandit"],"where":"on the road to Emberdeep","won":true,"close":false,"shape":"plain","reworded":-10,"wx":"rain"},{"id":"e2907","day":82,"season":3,"sday":22,"kind":"boss_race","imp":3,"text":"A race for Cindervast the Hoardmother: The Azure Gravediggers and Ottoline are all bound for Emberdeep. Only one of them gets the kill.","heroes":["h3","h15","h5","h9","h14"],"parties":["p3"],"loc":"emberdeep","wx":"fog"},{"id":"e2912","day":82,"season":3,"sday":22,"kind":"tarot","imp":2,"text":"Rook lays three cards on a flat stone for The Azure Gravediggers, with Emberdeep a short walk off in the dark: the Nine of Wands upside down, the Tower and the Queen of Swords. Rook suggests a different day for anything important.","heroes":["h3","h9"],"parties":["p3"],"loc":"emberdeep","reading":"r543","wx":"fog"},{"id":"e2913","day":82,"season":3,"sday":22,"kind":"talent","imp":1,"text":"Gorm banks the fire so there are still coals at dawn. Breakfast is twenty minutes sooner.","heroes":["h9"],"parties":["p3"],"loc":"emberdeep","skill":"firekeeper","wx":"fog"},{"id":"e2922","day":83,"season":3,"sday":23,"kind":"curse","imp":5,"text":"Duren throws the Whispering Crown into the fires of Emberdeep. Something screams on the way down.","heroes":["h3"],"parties":["p3"],"loc":"emberdeep","wx":"fog"},{"id":"e2937","day":83,"season":3,"sday":23,"kind":"delve","imp":1,"text":"The Azure Gravediggers descend into Emberdeep, untouched (0%).","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"emberdeep","wx":"fog"},{"id":"e2940","day":83,"season":3,"sday":23,"kind":"fight","imp":3,"text":"Three Fire Elementals and 2 Salamanders are too much for the Azure Gravediggers on floor 1 of Emberdeep, and it's time to run for it. Duren was the last one out and the angriest about it. \"Lean on me,\" says Duren.","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"emberdeep","fight":"f267","foes":["fire_elemental","salamander","fire_elemental"],"where":"on floor 1 of Emberdeep","won":false,"close":false,"shape":"foe","reworded":-21,"wx":"fog"},{"id":"e2941","day":83,"season":3,"sday":23,"kind":"rescue","imp":4,"text":"RESCUE in Emberdeep: Ottoline (Jamie's hero) finds Rook (Avery's hero) bleeding in the dark and does not walk past. 1 potion later, Rook is breathing properly.","heroes":["h14","h15","h3","h5","h9"],"parties":["p3"],"loc":"emberdeep","rescuers":["h14"],"wx":"fog"},{"id":"e2942","day":83,"season":3,"sday":23,"kind":"vow_broken","imp":4,"text":"So much for never to retreat: The Azure Gravediggers ran from a fight. The vow lasted 82 days.","heroes":["h3","h15","h5","h9"],"parties":["p3"],"cause":"e50"},{"id":"e2943","day":83,"season":3,"sday":23,"kind":"delve_done","imp":1,"text":"Driven out, The Azure Gravediggers climb out of Emberdeep after 1 day. They got down to floor 1. Emberdeep is now untouched (0%).","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"emberdeep","days":1,"bottom":false,"rooms":[],"gold":0,"out":"Driven out","wx":"fog"},{"id":"e2944","day":83,"season":3,"sday":23,"kind":"talent","imp":1,"text":"Morwen whittles a tiny wolf for Duren by the fire. Duren calls it silly and keeps it in a breast pocket. Chalk it up to Whittling.","heroes":["h5","h3"],"parties":["p3"],"loc":"emberdeep","skill":"whittler","wx":"fog"},{"id":"e2945","day":83,"season":3,"sday":23,"kind":"night","imp":3,"text":"Morwen tells a ghost story by the fire outside Emberdeep. Rook insists on keeping the fire going until dawn. For warmth.","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"emberdeep","wx":"fog"},{"id":"e2946","day":83,"season":3,"sday":23,"kind":"boss_race","imp":2,"text":"The race for Cindervast the Hoardmother is one crew lighter: The Azure Gravediggers turned for other work. That leaves Ottoline.","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"emberdeep","wx":"fog"},{"id":"e2949","day":83,"season":3,"sday":23,"kind":"meet","imp":2,"text":"Ottoline warns The Azure Gravediggers about what's lurking in Emberdeep. The Azure Gravediggers pretend to already know.","heroes":["h14","h3","h15","h5","h9"],"parties":["p3"],"loc":"emberdeep","wx":"fog"},{"id":"e2981","day":84,"season":3,"sday":24,"kind":"talent","imp":1,"text":"A farmer at Veldrock looks at Duren's egg, says 'that's no chicken', and won't elaborate.","heroes":["h3"],"parties":["p3"],"loc":"veldrock","wx":"fog"},{"id":"e2982","day":84,"season":3,"sday":24,"kind":"talent","imp":2,"text":"A queue forms at the Veldrock temple when word gets out Gorm is inside. He sees every single one.","heroes":["h9"],"parties":["p3"],"loc":"veldrock","skill":"living_saint","wx":"fog"},{"id":"e2983","day":84,"season":3,"sday":24,"kind":"ability","imp":2,"text":"The queue at the Veldrock almshouse runs round the block. Gorm sees every single one, and learns something from most of them.","heroes":["h9"],"parties":["p3"],"loc":"veldrock","skill":"almshouse_hours","sk":"Almshouse Hours","rule":true,"wx":"fog"},{"id":"e3012","day":85,"season":3,"sday":25,"kind":"talent","imp":1,"text":"Rook delivers a fair copy of an Ironhaven wizard's spellbook with the spelling corrected. The wizard pays up and sulks. Spellbook Copyist: one of the things Rook learned the long way round.","heroes":["h15"],"parties":["p3"],"loc":"ironhaven","skill":"spellbook_copyist"},{"id":"e3042","day":86,"season":3,"sday":26,"kind":"talent","imp":1,"text":"Rook corrects a Carrbridge veteran's war story with the date, the weather and the name of the general's horse.","heroes":["h15"],"parties":["p3"],"loc":"carrbridge","skill":"seen_it_in_a_book"},{"id":"e3054","day":86,"season":3,"sday":26,"kind":"campfire","imp":2,"text":"Tofu the cat won't sleep unless Gorm is in sight. Nobody can explain it.","heroes":["h15","h9"],"parties":["p3"],"loc":"carrbridge"},{"id":"e3098","day":88,"season":3,"sday":28,"kind":"night","imp":2,"text":"Rook tells a ghost story by the fire on the road to Veldrock. Duren laughs at it, then moves their bedroll closer to the others.","heroes":["h3","h15","h5","h9"],"parties":["p3"],"loc":"ironhaven"},{"id":"e3113","day":88,"season":3,"sday":28,"kind":"ledger","imp":2,"text":"THE LEDGER: 21 hauls sold this week, 2,061 silver in all. Biggest haul: Barnaby, 238 silver in Ironhaven. Back up from the deep: The Azure Gravediggers (1 day in Emberdeep), Ottoline (4 days in Emberdeep), Amber Banner (5 days in the Sunken Vault).","heroes":["h19","h3","h14","h18"],"parties":["p3","p2"]},{"id":"e3174","day":90,"season":3,"sday":30,"kind":"meet","imp":1,"text":"Fenwick and Duren swap stories in Emberdeep while The Mercy of Thornwall and The Azure Gravediggers swap rumours.","heroes":["h17","h11","h1","h14","h3","h15","h5","h9"],"parties":["p4","p3"],"loc":"emberdeep","wx":"snow"},{"id":"e3175","day":90,"season":3,"sday":30,"kind":"meet","imp":1,"text":"The Green Mercy and The Azure Gravediggers pass on the road between Emberdeep and Veldrock. Barnaby shares directions.","heroes":["h19","h20","h10","h16","h3","h15","h5","h9"],"parties":["p6","p3"],"loc":"emberdeep","wx":"snow"},{"id":"e3178","day":90,"season":3,"sday":30,"kind":"gift","imp":2,"text":"By the fire, Duren quietly hands Gorm an Egg That Is Still Warm. Gorm pockets it like it's treasure.","heroes":["h3","h9"],"parties":["p3"],"loc":"emberdeep","wx":"snow"},{"id":"e3180","day":90,"season":3,"sday":30,"kind":"tarot","imp":2,"text":"On the last night before Emberdeep, Rook spreads a cloak by the fire and reads the Bog-Warped Tarot for the whole of The Azure Gravediggers: the Star, the King of Pentacles and the Fool. The cards are kind.","heroes":["h3","h5"],"parties":["p3"],"loc":"emberdeep","reading":"r599","wx":"snow"},{"id":"e3185","day":90,"season":3,"sday":30,"kind":"talent","imp":2,"text":"Duren teaches Morwen to call a target in one word. Morwen picks 'that'.","heroes":["h3","h5"],"parties":["p3"],"loc":"emberdeep","skill":"mark_of_the_oath","wx":"snow"},{"id":"e3201","day":90,"season":3,"sday":30,"kind":"goal_missed","imp":3,"text":"Not this time: The Azure Gravediggers' goal (finish the season as one of the top three parties) falls short (finished 5th).","heroes":["h3","h15","h5","h9"],"parties":["p3"]}],"roles":{"h15":"Spellcaster","h9":"Healer","h5":"Tracker","h3":"Leader · Shield"},"quest":{"what":"Delve","where":"Emberdeep","why":"racing The Newts of Ashfen to the boss: about 25 silver a day each, risk real; the season goal: to finish the season as one of the top three parties; Duren's last chance at the dream before the age ends","floor":0,"floors":5},"tactics":{"front":["h3","h9"],"back":["h15","h5"],"plan":"Duren and Gorm hold the front; Rook casts from behind; Morwen picks off whatever gets close; Duren, Rook and Gorm keep everyone standing.","traits":{"boldness":0.6,"risk":-0.14,"greed":-0.61,"sociability":-0.2,"honor":0.7,"curiosity":-0.21,"temper":0.12,"loyalty":0.18},"mix":"2 blades, 1 caster, 1 bow","notes":[],"style":["bold","balanced"],"skills":[{"label":"Damage","skills":[{"hero":"h15","id":"unravelling_word","name":"The Unravelling Word","desc":"Pronounces it correctly. That's the dangerous part.","tags":[],"rank":1,"uses":23},{"hero":"h3","id":"mark_of_the_oath","name":"Mark of the Oath","desc":"Points at the worst one in the room. Everyone follows the finger.","tags":[],"rank":1,"uses":21},{"hero":"h15","id":"force_bolt","name":"Force Bolt","desc":"An invisible fist, thrown from across the room.","tags":["arcane"],"rank":3,"uses":17},{"hero":"h5","id":"thorn_whip","name":"Thorn Whip","desc":"A vine with ideas.","tags":["nature"],"rank":2,"uses":17},{"hero":"h9","id":"smite","name":"Smite","desc":"Radiant and righteous. Double against the dead.","tags":["holy"],"rank":3,"uses":15},{"hero":"h9","id":"judgement","name":"Judgement","desc":"The verdict is in. It is heavy.","tags":["holy"],"rank":3,"uses":13},{"hero":"h3","id":"turn_undead","name":"Turn Undead","desc":"Begone.","tags":["holy"],"rank":3,"uses":9},{"hero":"h5","id":"pan_to_the_face","name":"Pan to the Face","desc":"The frying pan was for cooking. Was.","tags":[],"rank":1,"uses":9},{"hero":"h15","id":"annotated_bolt","name":"Annotated Bolt","desc":"Hits them, then cites the source.","tags":["lore","arcane"],"rank":1,"uses":7},{"hero":"h5","id":"natures_wrath","name":"Nature's Wrath","desc":"The forest fights back.","tags":["nature"],"rank":1,"uses":5},{"hero":"h9","id":"feint","name":"Feint","desc":"Look over there.","tags":["stealth","crit"],"rank":1,"uses":4},{"hero":"h15","id":"magic_missile","name":"Magic Missile","desc":"Three darts of light. Usually all three land.","tags":["arcane"],"rank":2,"uses":2},{"hero":"h15","id":"arcane_torrent","name":"Arcane Torrent","desc":"Opens the book and lets it out.","tags":["arcane"],"rank":1,"uses":2},{"hero":"h9","id":"pan_to_the_face","name":"Pan to the Face","desc":"The frying pan was for cooking. Was.","tags":[],"rank":1,"uses":1}]},{"label":"Healing","skills":[{"hero":"h9","id":"lay_on_hands","name":"Lay on Hands","desc":"A warm palm, a closed wound.","tags":["holy","heal"],"rank":1,"uses":9},{"hero":"h15","id":"rejuvenate","name":"Rejuvenate","desc":"Green light washes over the party.","tags":["nature","heal"],"rank":1,"uses":6},{"hero":"h3","id":"field_dressing","name":"Field Dressing","desc":"Moss, spit and a clean-ish rag.","tags":["heal"],"rank":1,"uses":2},{"hero":"h15","id":"mend_wounds","name":"Mend Wounds","desc":"Knits flesh with a word.","tags":["heal","holy"],"rank":1,"uses":2},{"hero":"h9","id":"miracle","name":"Miracle","desc":"Witnesses still argue about what they saw.","tags":["holy","heal"],"rank":2,"uses":2},{"hero":"h9","id":"healing_word","name":"Healing Word","desc":"A kind word that closes a cut.","tags":["heal"],"rank":1,"uses":0}]},{"label":"Defence","skills":[{"hero":"h5","id":"call_of_the_wild","name":"Call of the Wild","desc":"Something in the trees answers. Everyone feels braver and slightly hairier.","tags":["nature","beast"],"rank":2,"uses":25},{"hero":"h9","id":"battle_cry","name":"Battle Cry","desc":"Bellows something inspiring and mostly vowels. Everyone swings harder.","tags":["command","rage"],"rank":1,"uses":15},{"hero":"h3","id":"intercept","name":"Intercept","desc":"Steps in front of the blow meant for a friend.","tags":["guard"],"rank":1,"uses":14},{"hero":"h3","id":"divine_shield","name":"Divine Shield","desc":"Golden light, briefly.","tags":["holy","guard"],"rank":3,"uses":12},{"hero":"h3","id":"sun_standard","name":"Sun Standard","desc":"Raises the standard. Everyone tries to look worthy of it.","tags":["holy"],"rank":2,"uses":4}]},{"label":"Tricks","skills":[{"hero":"h5","id":"ambush","name":"Ambush","desc":"The party always strikes first.","tags":["stealth","nature"],"rank":3,"uses":35},{"hero":"h3","id":"oath_of_light","name":"Oath of Light","desc":"Says the oath before the first blow. The oath is long. The armour holds.","tags":["holy"],"rank":3,"uses":26},{"hero":"h15","id":"cold_snap","name":"Cold Snap","desc":"The temperature drops ten degrees, on purpose.","tags":["ice"],"rank":1,"uses":8},{"hero":"h9","id":"captains_call","name":"Captain's Call","desc":"When one falls, the rest hit harder for them.","tags":["command","rage"],"rank":1,"uses":2},{"hero":"h3","id":"shepherd_of_the_fallen","name":"Shepherd of the Fallen","desc":"Counts the flock after every fall, and mends whoever is left.","tags":[],"rank":1,"uses":1},{"hero":"h15","id":"seen_it_in_a_book","name":"Seen It in a Book","desc":"Knows what a goblin warband does next. Read about it. Took notes.","tags":[],"rank":1,"uses":0},{"hero":"h5","id":"camouflage","name":"Camouflage","desc":"Becomes a bush. A suspicious bush.","tags":["stealth","nature"],"rank":3,"uses":0},{"hero":"h5","id":"heart_of_the_wild","name":"Heart of the Wild","desc":"More forest than person. Very sturdy forest.","tags":[],"rank":1,"uses":0},{"hero":"h9","id":"living_saint","name":"Living Saint","desc":"Small miracles, daily. Paperwork, endless.","tags":[],"rank":1,"uses":0}]},{"label":"Always on","skills":[{"hero":"h15","id":"know_thy_enemy","name":"Know Thy Enemy","desc":"Read the bestiary. Twice.","tags":["lore"],"rank":1,"uses":0},{"hero":"h15","id":"lore","name":"Ancient Lore","desc":"Knows every monster's weakness from a book.","tags":["arcane","lore"],"rank":2,"uses":0},{"hero":"h5","id":"beast_lore","name":"Beast Lore","desc":"Knows where it hurts.","tags":["beast","nature"],"rank":1,"uses":0},{"hero":"h9","id":"aura_of_courage","name":"Aura of Courage","desc":"Nobody runs while they stand.","tags":["holy","command"],"rank":1,"uses":0}]},{"label":"On the road","skills":[{"hero":"h3","id":"hymn_singer","name":"Hymn Singer","desc":"Sings the old hymns in a voice like a warm bath.","tags":["holy","music"],"rank":1,"uses":0},{"hero":"h3","id":"devout","name":"Devout","desc":"Temples patch them up for less.","tags":["holy"],"rank":1,"uses":0},{"hero":"h3","id":"trail_baker","name":"Trail Baker","desc":"Bread on the road. Actual bread.","tags":[],"rank":1,"uses":0},{"hero":"h3","id":"drinking_songs","name":"Drinking Songs","desc":"Knows every verse. Especially the forbidden ones.","tags":["music","rage"],"rank":1,"uses":0},{"hero":"h3","id":"honey_finder","name":"Honey Finder","desc":"Follows the bees. Comes back sticky.","tags":[],"rank":1,"uses":0},{"hero":"h3","id":"camp_cook","name":"Camp Cook","desc":"Makes rations taste like dinner. Party morale up.","tags":[],"rank":1,"uses":0},{"hero":"h3","id":"dice_luck","name":"Dice Luck","desc":"Rolls sixes when it matters, and only then.","tags":["trade","crit"],"rank":1,"uses":0},{"hero":"h15","id":"everburning_light","name":"Everburning Light","desc":"A light that won't go out, even when it should.","tags":["arcane"],"rank":1,"uses":0},{"hero":"h15","id":"portal_stone","name":"Portal Stone","desc":"Knows a door in this wall that opens in the next town. Mostly.","tags":["arcane"],"rank":1,"uses":0},{"hero":"h15","id":"honey_finder","name":"Honey Finder","desc":"Follows the bees. Comes back sticky.","tags":[],"rank":1,"uses":0},{"hero":"h15","id":"detect_magic","name":"Detect Magic","desc":"Knows a relic's worth at a glance.","tags":["arcane","trade"],"rank":1,"uses":0},{"hero":"h15","id":"spellbook_copyist","name":"Spellbook Copyist","desc":"Copies spellbooks for wizards too busy to read their own.","tags":["arcane"],"rank":1,"uses":0},{"hero":"h15","id":"ward_inspector","name":"Ward Inspector","desc":"Checks the inn's wards before bed. Always finds a gap. Fixes it.","tags":["guard","arcane"],"rank":1,"uses":0},{"hero":"h15","id":"warding_circle","name":"Warding Circle","desc":"Chalks a circle round the camp. Things stay outside it.","tags":["arcane"],"rank":1,"uses":0},{"hero":"h5","id":"knot_tying","name":"Knotwork","desc":"Knows forty knots and when to use thirty-nine of them.","tags":["travel","craft"],"rank":1,"uses":0},{"hero":"h5","id":"game_hunter","name":"Game Hunter","desc":"Comes back from a short walk with dinner.","tags":["nature","beast"],"rank":1,"uses":0},{"hero":"h5","id":"firekeeper","name":"Firekeeper","desc":"Lights a fire in a rainstorm, with wet wood, every time.","tags":[],"rank":1,"uses":0},{"hero":"h5","id":"herbalism","name":"Herbalism","desc":"Knows every useful leaf.","tags":["nature","heal"],"rank":1,"uses":0},{"hero":"h5","id":"mule_whisperer","name":"Mule Whisperer","desc":"Mules listen to them. Nobody knows why.","tags":["beast","travel"],"rank":1,"uses":0},{"hero":"h5","id":"kennel_keeper","name":"Kennel Keeper","desc":"Brings a dog to camp. Nobody has a bad night with a dog in camp.","tags":["beast"],"rank":1,"uses":0},{"hero":"h5","id":"whittler","name":"Whittling","desc":"Turns every stick into a small duck.","tags":[],"rank":1,"uses":0},{"hero":"h9","id":"letter_writer","name":"Letter Writer","desc":"Writes home. Writes everyone's home.","tags":["lore"],"rank":1,"uses":0},{"hero":"h9","id":"hymn_singer","name":"Hymn Singer","desc":"Sings the old hymns in a voice like a warm bath.","tags":["holy","music"],"rank":1,"uses":0},{"hero":"h9","id":"firekeeper","name":"Firekeeper","desc":"Lights a fire in a rainstorm, with wet wood, every time.","tags":[],"rank":1,"uses":0},{"hero":"h9","id":"pilgrim","name":"Pilgrim","desc":"Every road leads to a shrine, if you walk it right.","tags":["holy","travel"],"rank":1,"uses":0},{"hero":"h9","id":"house_calls","name":"House Calls","desc":"Visits the sick in every town. Starts with the crew.","tags":["heal","holy"],"rank":1,"uses":0}]}],"share":[{"hero":"h3","dmg":512,"healed":113,"taken":545,"kills":1,"row":"front"},{"hero":"h15","dmg":2117,"healed":0,"taken":199,"kills":11,"row":"back"},{"hero":"h5","dmg":1734,"healed":0,"taken":95,"kills":3,"row":"back"},{"hero":"h9","dmg":705,"healed":275,"taken":264,"kills":2,"row":"front"}],"ground":{"name":"The Ashveil Crypts","fights":8}},"trophies":[{"boss":"The Mimic King","monster":"mimic_king","place":"Cragtooth Warren","day":17,"season":1,"fight":"f75"},{"boss":"Vessimir the Unburied's Avenger","monster":"necromancer","place":"The Ashveil Crypts","day":36,"season":2,"fight":"f128"}]};